QX('x-inv2', 'נסו לבד', 'מכוניות המזרח: שנתיים של מלאי',
   ['מכוניות המזרח בע״מ מייבאת מכוניות חשמליות ומוכרת אותן לסוכנויות. בגיליון: עלות המכר של כל שנה, והמלאי בתחילת כל שנה ובסופה, במיליוני ש״ח.',
    '<b>נדרש א:</b> חשבו לכל שנה את המלאי הממוצע, את מחזור המלאי ואת ימי המלאי.', '<b>נדרש ב:</b> מה השתנה, ומה עשוי להסביר את השינוי?'],
   'מלאו את שורות 6 עד 8 בעמודה B, וגררו לעמודה C.',
   {'A1': 'מכוניות המזרח, מיליוני ש״ח', 'B1': 'שנת 2026', 'C1': 'שנת 2025', 'A2': 'מלאי בתחילת השנה', 'A3': 'מלאי בסוף השנה', 'A4': 'עלות המכר', 'A6': 'מלאי ממוצע', 'A7': 'מחזור מלאי', 'A8': 'ימי מלאי'},
   {'B6': '=AVERAGE(B2:B3)', 'C6': '=AVERAGE(C2:C3)', 'B7': '=B4/B6', 'C7': '=C4/C6', 'B8': '=365/B7', 'C8': '=365/C7'}, [230, 100, 100], [1],
   given={'B2': 340, 'C2': 300, 'B3': 620, 'C3': 340, 'B4': 1460, 'C4': 1460},
   fmt={**{f'{c}{r}': 'num0' for c in 'BC' for r in (2, 3, 4, 6)}, **{f'{c}7': 'num2' for c in 'BC'}, **{f'{c}8': 'num1' for c in 'BC'}}, sty=_HD(),
   hints=['מלאי ממוצע: =AVERAGE(B2:B3). מחזור: =B4/B6. ימים: =365/B7.', 'כתבו את שלוש הנוסחאות בעמודה B, וגררו אותן לעמודה C.'], remind='=B4/B6   =365/B7',
   traps={'B7': [('=B6/B4', 'הפכתם את היחס: עלות המכר במונה, =B4/B6.')]},
   steps=[dict(cells={'B6': '=AVERAGE(B2:B3)'}, note='2026: הממוצע של 340 ושל 620, כלומר 480.'), dict(cells={'C6': '=AVERAGE(C2:C3)'}, note='2025: הממוצע של 300 ושל 340, כלומר 320.'),
          dict(cells={'B7': '=B4/B6'}, note='מחזור 2026: 1,460 חלקי 480, כ-3.04.'), dict(cells={'C7': '=C4/C6'}, note='מחזור 2025: 1,460 חלקי 320, כ-4.56.'),
          dict(cells={'B8': '=365/B7'}, note='ימי מלאי 2026: 120.'), dict(cells={'C8': '=365/C7'}, note='ימי מלאי 2025: 80.')],
   qmc=_DI + MORE('תשובה לנדרש ב', ['עלות המכר לא השתנתה, אבל המלאי בסוף 2026 כמעט כפול מבסוף 2025: 620 מול 340. לכן ימי המלאי עלו מ-80 ל-120.',
                                     'הסבר שלילי: הביקוש נחלש, והמכוניות לא נמכרות. אז צפויות הנחות, ואולי גם הפרשה לירידת ערך המלאי.',
                                     'הסבר שאינו בהכרח שלילי: החברה ייבאה מראש, לפני שינוי צפוי במחיר או במס. כדי להכריע קוראים את דוח הדירקטוריון ואת ביאור המלאי.']),
   note=[('ans', 'שנת 2026: מלאי ממוצע 480, מחזור 3.04, ימי מלאי 120.0. שנת 2025: 320, 4.56, 80.0.', 1)],
   done='2026: 480, 3.04, 120.0. 2025: 320, 4.56, 80.0.', xtitle='מכוניות המזרח: ימי מלאי בשנתיים')

_SRC = lambda t: f'<p class="srcl">{TX(t)}</p>'
S('w-inv', 'מהעולם: מלאי שגדל', 'מהעולם: מלאי שגדל ב-2026. בעיה, או החלטה?',
  '<div class="row eq2 top">'
  + PRESS(1, 'מעריב', '8.7.2026', 'יבוא הרכב זינק, המסירות כמעט לא זזו',
          'בינואר עד יוני 2026 יובאו לישראל כ-152,700 כלי רכב, 54.8% יותר מבתקופה המקבילה. המסירות ללקוחות בינואר עד מאי עלו בכ-1% בלבד. ההפרש נשאר במגרשים של היבואנים.',
          'https://www.maariv.co.il/economy/israel/article-1342164', 'ביחסים: המלאי גדל מהר מהמכירות, וימי המלאי עולים. בנובמבר היבואנים כבר מציעים הנחות של סוף שנה.')
  + PRESS(2, 'Apple, הדוח השנתי', '26.9.2026', 'אפל מילאה את המחסן ברכיבים',
          'המלאי של אפל עלה מ-5.7 ל-14.5 מיליארד דולר. רוב הגידול ברכיבים: מ-2.1 ל-10.4 מיליארד. בדוח מסבירה החברה שיש מחסור ועליית מחירים ברכיבים, ובעיקר בזיכרון ובאחסון.',
          'https://www.sec.gov/Archives/edgar/data/320193/000032019326000026/aapl-20260926.htm', 'ביחסים: גם כאן ימי המלאי עלו, אבל בכוונה. במחסור, מלאי של רכיבים הוא ביטחון לייצור.')
  + '</div>' + BAND('dg', 'אותו יחס, שני סיפורים הפוכים. כדי להבחין ביניהם, פותחים את ביאור המלאי: חומרי גלם ורכיבים שנאגרו לקראת ייצור, או מוצרים מוגמרים שלא נמכרים.', 3), kick='חלק 3 · מהעולם האמיתי')

